head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > closeonmouseleave]<br/>마우스가 SelectBox 컴포넌트 영역을 벗어날때 표시된 아이템 리스트를 닫을지 여부를 설정합니다.",
    "validation" : [
        "renderType=component 이고, 아이템 정의가 BindItemSet 인 경우 동작합니다.",
        "미설정 시 마우스가 컴포넌트 영역을 벗어나도 표시된 아이템 리스트를 유지합니다.",
        "true 설정 시 마우스가 컴포넌트 영역(아이템 리스트 영역 포함)을 벗어나면 표시된 아이템 리스트를 닫습니다.",
        "false 설정 시 마우스가 컴포넌트 영역을 벗어나도 표시된 아이템 리스트를 유지합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        closeonmouseleave : con_closeonmouseleave.getText(),
    }

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["onmouseleave"]);

    // comp 생성 함수 호출
    $c.gcm.createBasicAutoComplete(cList, eList);
}



scwin.get_isItemList_onclick = function (e) {
    // id에 "target1_itemTable" 문자열이 포함된 div 요소를 선택합니다.
    let divs = document.querySelectorAll('div[id*="target1_itemTable"]');

    // 각 div 요소에 대해 작업을 수행
    divs.forEach(div => {
        // style의 display와 visibility 값을 가져옵니다.
        let displayValue = div.style.display;
        let visibilityValue = div.style.visibility;

        // 결과를 출력합니다.
        wf_body_bottom.getObj("scwin").setReturnValue("display : " + displayValue);
        wf_body_bottom.getObj("scwin").setReturnValue("visibility : " + visibilityValue);
    });	
};



scwin.target1_onmouseleave = function (e) {
    scwin.get_isItemList_onclick();
}
